  it('error still propagates after onError hook', async () => {
    const hooks: OrchestratorHooks = {
      onError: async () => {},
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
  });

  it('wraps a non-Error rejection in an Error carrying the raw value as cause and rethrows the original', async () => {
    let receivedError: Error | undefined;
    const rawRejection = 'non-error rejection';
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw rawRejection;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    const caught = await orchestrator.processMessage(createSession('hello')).catch((err: unknown) => err);

    expect({
      caught,
      isError: receivedError instanceof Error,
      message: receivedError?.message,
      cause: receivedError?.cause,
    }).toEqual({
      caught: rawRejection,
      isError: true,
      message: rawRejection,
      cause: rawRejection,
    });
  });
});

