function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!acc) return next;
  if (!next) return acc;
  return {
    inputTokens: acc.inputTokens + next.inputTokens,
    outputTokens: acc.outputTokens + next.outputTokens,
    totalTokens: acc.totalTokens + next.totalTokens,
  };
}

// Wraps a non-Error rejection so onError keeps its Error signature while exposing the raw value on cause.
function toError(error: unknown): Error {
  if (error instanceof Error) return error;
  return new Error(String(error), {cause: error});
}

